import * as React from "react";

export function BlurTextFlow({ words = ["Clarity", "Focus", "Precision", "Vision"], className = "" }: { words?: string[]; className?: string }): React.JSX.Element {
  const [i, setI] = React.useState(0);
  const [phase, setPhase] = React.useState<"in" | "out">("in");
  React.useEffect(() => {
    const id = setTimeout(() => {
      if (phase === "in") { setTimeout(() => setPhase("out"), 1500); }
      else { setI(p => (p + 1) % words.length); setPhase("in"); }
    }, phase === "in" ? 400 : 400);
    return () => clearTimeout(id);
  }, [phase, words.length]);
  return (
    <div className={`text-center select-none ${className}`}>
      <span className="font-display font-black text-5xl text-ink" style={{ display: "inline-block", filter: phase === "in" ? "blur(0px)" : "blur(16px)", opacity: phase === "in" ? 1 : 0, transform: phase === "in" ? "scale(1)" : "scale(0.92)", transition: "all 0.35s cubic-bezier(0.4,0,0.2,1)" }}>
        {words[i]}
      </span>
    </div>
  );
}

import * as React from "react";
import { BlurTextFlow } from "./blur-text-flow";

export default function BlurTextFlowDemo(): React.JSX.Element {
  return (
    <div className="flex min-h-[360px] w-full items-center justify-center rounded-2xl bg-neutral-950 p-8 border border-neutral-800">
      <BlurTextFlow
        text="Next Generation Web Interfaces"
        className="text-3xl sm:text-5xl font-mono font-bold tracking-tight text-white text-center"
      />
    </div>
  );
}
